{
  "headline": "Olanzapine is not on FDA's shortage list as of 2026-10-21; a registered plant for a labeled product has OAI inspections and recent Class II and Class III recalls for olanzapine tablets",
  "headline_cites": ["D4", "E10", "E7", "E8", "E11", "E12", "E13"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include olanzapine as of 2026-10-21.",
      "cites": ["D4"]
    },
    {
      "text": "A product label for olanzapine 10 mg (NDC 33342008411) names Macleods Pharmaceuticals Limited as the labeler and a registered plant (FEI 3007517881) in India.",
      "cites": ["E10"]
    },
    {
      "text": "That plant received OAI classifications after inspections ending 2017-11-24 and 2021-11-01.",
      "cites": ["E7", "E8"]
    },
    {
      "text": "The same plant was subject to a Class II recall of olanzapine 10 mg tablets initiated 2022-02-16 (D-0639-2022), a Class II recall of olanzapine 2.5 mg tablets initiated 2024-11-25 (D-0154-2025), and a Class III recall of olanzapine 5 mg tablets initiated 2026-08-27 (D-0867-2026), all for cGMP deviations or failed impurity specifications.",
      "cites": ["E11", "E12", "E13"]
    },
    {
      "text": "Current inventory across three sites ranges from 11.7 to 28.8 days on hand for the 10 mg tablet presentation.",
      "cites": ["D1", "D2", "D3"]
    },
    {
      "text": "The rule-based alternate manufacturer ranked first is Alkermes, Inc., which is not on FDA's shortage list today, though its label names no plant we could place.",
      "cites": ["D5"]
    }
  ]
}
